// Extract incident payload from incoming webhook body
const payload = $input.first().json.body || $input.first().json;

const incidentId = payload.incident_id || `INC-${Date.now().toString(36).toUpperCase()}`;
const severity = (payload.severity || 'P2').toUpperCase();
const title = payload.title || 'Infrastructure Incident Alert';
const summary = payload.summary || payload.query || 'Unspecified incident query';
const matchedRunbooks = payload.matched_runbooks || [];
const diagnostics = payload.diagnostics || {};
const remediationPlan = payload.remediation_plan || payload.remediation || 'Follow standard operating procedure.';
const timestamp = new Date().toISOString();

// Color mapping based on SRE severity level
const severityColors = {
  'P1': '#E02424', // Red (Critical)
  'P2': '#FF5A1F', // Orange (High)
  'P3': '#E3A008', // Amber (Medium)
  'P4': '#3F83F8'  // Blue (Low)
};
const color = severityColors[severity] || '#76A9FA';

// Build Markdown formatted alert
const formattedMarkdown = [
  `🚨 **[${severity}] ${title}**`,
  `**Incident ID**: \`${incidentId}\` | **Time**: ${timestamp}`,
  `**Summary**: ${summary}`,
  '',
  `📊 **Diagnostic Telemetry**:`,
  '```json',
  JSON.stringify(diagnostics, null, 2),
  '```',
  '',
  `📖 **Matched Runbooks**: ${matchedRunbooks.map(r => typeof r === 'string' ? r : r.title || r.filename).join(', ') || 'None'}`,
  '',
  `🛠️ **Actionable Remediation Plan**:`,
  remediationPlan
].join('\n');

// Slack / Discord compatible webhook payload block
const notificationPayload = {
  incident_id: incidentId,
  severity,
  title,
  timestamp,
  formatted_markdown: formattedMarkdown,
  slack_payload: {
    text: `🚨 [${severity}] ${title}`,
    attachments: [{
      color: color,
      title: `[${severity}] ${title}`,
      text: formattedMarkdown,
      ts: Math.floor(Date.now() / 1000)
    }]
  },
  discord_payload: {
    embeds: [{
      title: `🚨 [${severity}] ${title}`,
      description: formattedMarkdown,
      color: parseInt(color.replace('#', ''), 16),
      timestamp: timestamp
    }]
  }
};

return [{
  json: {
    status: 'received',
    success: true,
    dispatched_at: timestamp,
    incident_id: incidentId,
    severity: severity,
    title: title,
    notification: notificationPayload
  }
}];
